∀ (p u v : Prop),
  let U := fun x => x = True ∨ p;
  let V := fun x => x = False ∨ p;
  ∀ (motive : U u → V v → Prop) (u_def : U u) (v_def : V v),
    (∀ (h : p) (x : V v), motive ⋯ x) →
      (∀ (x : U u) (h : p), motive x ⋯) → (∀ (hut : u = True) (hvf : v = False), motive ⋯ ⋯) → motive u_def v_def

∀ {n : ℕ} {motive : (a : ℕ) → n.le a → Prop} {motive_1 : {a : ℕ} → (t : n.le a) → Nat.le.below t → Prop} {a : ℕ}
  {t : n.le a} (t_1 : Nat.le.below t),
  motive_1 ⋯ ⋯ → (∀ {m : ℕ} (a : n.le m) (ih : Nat.le.below a) (a_ih : motive m a), motive_1 ⋯ ⋯) → motive_1 t t_1
